package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DSCompiler_atan2_TriageGen2Test {

    private DSCompiler compiler;
    private static final double EPSILON = 1e-12;

    @Before
    public void setUp() {
        // Using a small size to keep tests manageable. 
        // getSize() is used internally by the method.
        compiler = DSCompiler.getCompiler(1, 1);
    }

    /**
     * Tests the branch where x[xOffset] >= 0.
     * This covers the first half of the if-else block.
     */
    @Test
    public void testAtan2_PositiveX() {
        int size = compiler.getSize();
        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Case: x > 0, y > 0 (First Quadrant)
        y[0] = 1.0;
        x[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Quadrant I failed", FastMath.atan2(1.0, 1.0), result[0], EPSILON);

        // Case: x = 0, y > 0 (Boundary x >= 0)
        y[0] = 1.0;
        x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Boundary x=0 failed", FastMath.atan2(1.0, 0.0), result[0], EPSILON);

        // Case: x > 0, y = 0
        y[0] = 0.0;
        x[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("y=0 failed", FastMath.atan2(0.0, 1.0), result[0], EPSILON);
    }

    /**
     * Tests the branch where x[xOffset] < 0.
     * This covers the second half of the if-else block.
     */
    @Test
    public void testAtan2_NegativeX() {
        int size = compiler.getSize();
        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Case: x < 0, y > 0 (Second Quadrant)
        y[0] = 1.0;
        x[0] = -1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Quadrant II failed", FastMath.atan2(1.0, -1.0), result[0], EPSILON);

        // Case: x < 0, y < 0 (Third Quadrant)
        y[0] = -1.0;
        x[0] = -1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Quadrant III failed", FastMath.atan2(-1.0, -1.0), result[0], EPSILON);

        // Case: x < 0, y = 0 (Boundary)
        y[0] = 0.0;
        x[0] = -1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("y=0 with negative x failed", FastMath.atan2(0.0, -1.0), result[0], EPSILON);
    }

    /**
     * Tests special cases (Infinities and Zeros) to ensure the final 
     * assignment result[resultOffset] = FastMath.atan2(...) works as intended.
     */
    @Test
    public void testAtan2_SpecialValues() {
        int size = compiler.getSize();
        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Infinity case
        y[0] = Double.POSITIVE_INFINITY;
        x[0] = 1.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Positive Infinity failed", FastMath.atan2(Double.POSITIVE_INFINITY, 1.0), result[0], EPSILON);

        // Zero case (+0, -0)
        y[0] = 0.0;
        x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Zero case failed", FastMath.atan2(0.0, 0.0), result[0], EPSILON);

        y[0] = -0.0;
        x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        assertEquals("Negative Zero case failed", FastMath.atan2(-0.0, 0.0), result[0], EPSILON);
    }

    /**
     * Tests with offsets to ensure the method respects the offset parameters.
     */
    @Test
    public void testAtan2_WithOffsets() {
        int size = 5;
        // Create a larger compiler context to allow offsets
        compiler = DSCompiler.getCompiler(1, 1); 
        // Note: Since we can't easily change getSize() via constructor in this snippet, 
        // we rely on the fact that it's used for tmp arrays.

        double[] y = new double[10];
        double[] x = new double[10];
        double[] result = new double[10];

        int yOff = 2;
        int xOff = 3;
        int resOff = 5;

        y[yOff] = 1.0;
        x[xOff] = 1.0;

        compiler.atan2(y, yOff, x, xOff, result, resOff);

        assertEquals("Offset handling failed", FastMath.atan2(1.0, 1.0), result[resOff], EPSILON);
    }
}
